// Where compiled agent files live (C10). Light: used by the hooks to protect them.

export const MARKER =
  "<!-- Generated by capsules from .capsules/. Do not edit. Run: capsules compile -->";
export const AGENTS_BEGIN = "<!-- capsules:begin -->";
export const AGENTS_END = "<!-- capsules:end -->";

/** A file only `capsules compile` may write (the AGENTS.md block is checked separately). */
export function isGeneratedPath(path: string): boolean {
  return (
    /^\.claude\/rules\/capsules-[^/]+\.md$/.test(path) ||
    /^\.cursor\/rules\/capsules-[^/]+\.mdc$/.test(path)
  );
}

/** The managed block of an AGENTS.md file, or null if it has none. */
export function agentsBlock(text: string): string | null {
  const t = text.replace(/\r\n?/g, "\n");
  const i = t.indexOf(AGENTS_BEGIN);
  const j = t.indexOf(AGENTS_END);
  return i >= 0 && j > i ? t.slice(i, j + AGENTS_END.length) : null;
}
